"""Component tree walking and validation for tightly-coupled plugin suites."""

from __future__ import annotations

import logging
from pathlib import Path
from typing import TYPE_CHECKING

from hcli.lib.ida.plugin import (
    IDAMetadataDescriptor,
    get_metadatas_with_paths_from_plugin_archive,
)

if TYPE_CHECKING:
    from hcli.lib.ida.plugin.install import InstalledPluginRecord

logger = logging.getLogger(__name__)

MAX_COMPONENT_DEPTH = 10


def walk_component_tree_from_directory(
    plugin_dir: Path,
    *,
    _depth: int = 0,
) -> list[tuple[Path, IDAMetadataDescriptor]]:
    """Walk a suite's component tree on disk, validating as we go.

    Returns a flat list of (path, descriptor) for every component found
    at any nesting depth. The suite itself is NOT included.

    Raises:
        ValueError: on missing subdirectory, name mismatch, or depth exceeded.
    """
    if _depth >= MAX_COMPONENT_DEPTH:
        raise ValueError(f"component nesting exceeds maximum depth ({MAX_COMPONENT_DEPTH})")

    metadata = _read_metadata_from_directory(plugin_dir)
    result: list[tuple[Path, IDAMetadataDescriptor]] = []

    for component_name in metadata.plugin.components:
        component_dir = plugin_dir / component_name
        if not component_dir.is_dir():
            raise ValueError(
                f"component '{component_name}' declared by '{metadata.plugin.name}' "
                f"but subdirectory not found: {component_dir}"
            )

        component_metadata = _read_metadata_from_directory(component_dir)
        if component_metadata.plugin.name != component_name:
            raise ValueError(
                f"component directory '{component_name}' contains plugin "
                f"'{component_metadata.plugin.name}' (name mismatch)"
            )

        result.append((component_dir, component_metadata))
        result.extend(walk_component_tree_from_directory(component_dir, _depth=_depth + 1))

    return result


def walk_component_tree_from_archive(
    zip_data: bytes,
    root_path: Path,
    root_metadata: IDAMetadataDescriptor,
    *,
    _depth: int = 0,
    _all_metadatas: dict[str, tuple[Path, IDAMetadataDescriptor]] | None = None,
) -> list[tuple[Path, IDAMetadataDescriptor]]:
    """Walk a suite's component tree inside a zip archive, validating as we go.

    Returns a flat list of (archive_path, descriptor) for every component
    found at any nesting depth. The root manifest is NOT included.

    Raises:
        ValueError: on missing component, name mismatch, or depth exceeded.
    """
    if _depth >= MAX_COMPONENT_DEPTH:
        raise ValueError(f"component nesting exceeds maximum depth ({MAX_COMPONENT_DEPTH})")

    if _all_metadatas is None:
        _all_metadatas = {}
        for path, meta in get_metadatas_with_paths_from_plugin_archive(zip_data):
            _all_metadatas[meta.plugin.name] = (path, meta)

    root_dir = root_path.parent
    result: list[tuple[Path, IDAMetadataDescriptor]] = []

    for component_name in root_metadata.plugin.components:
        if component_name not in _all_metadatas:
            expected_dir = root_dir / component_name
            raise ValueError(
                f"component '{component_name}' declared by '{root_metadata.plugin.name}' "
                f"but no ida-plugin.json found under {expected_dir}"
            )

        comp_path, comp_meta = _all_metadatas[component_name]
        if comp_meta.plugin.name != component_name:
            raise ValueError(
                f"component '{component_name}' manifest has plugin.name '{comp_meta.plugin.name}' (name mismatch)"
            )

        result.append((comp_path, comp_meta))
        result.extend(
            walk_component_tree_from_archive(
                zip_data,
                comp_path,
                comp_meta,
                _depth=_depth + 1,
                _all_metadatas=_all_metadatas,
            )
        )

    return result


def collect_all_component_names_from_archive(
    zip_data: bytes,
    root_path: Path,
    root_metadata: IDAMetadataDescriptor,
) -> set[str]:
    """Collect all component names in a suite archive (at any depth)."""
    tree = walk_component_tree_from_archive(zip_data, root_path, root_metadata)
    return {meta.plugin.name for _, meta in tree}


def find_root_manifest_in_archive(
    zip_data: bytes,
) -> tuple[Path, IDAMetadataDescriptor]:
    """Identify the root manifest in a multi-manifest archive.

    The root is the manifest whose plugin.name is not listed as a component
    by any other manifest in the archive.

    Raises:
        ValueError: if zero or multiple root candidates exist.
    """
    all_items = list(get_metadatas_with_paths_from_plugin_archive(zip_data))
    if not all_items:
        raise ValueError("no valid ida-plugin.json found in archive")

    if len(all_items) == 1:
        return all_items[0]

    referenced_as_component: set[str] = set()
    for _, meta in all_items:
        referenced_as_component.update(meta.plugin.components)

    roots = [(path, meta) for path, meta in all_items if meta.plugin.name not in referenced_as_component]

    if len(roots) == 0:
        raise ValueError("circular component references: every manifest is referenced as a component")
    if len(roots) > 1:
        names = ", ".join(meta.plugin.name for _, meta in roots)
        raise ValueError(f"archive contains multiple unrelated plugins ({names}); specify which one to install")

    return roots[0]


def find_suite_for_component(name: str) -> InstalledPluginRecord | None:
    """If *name* is a component of an installed suite, return that suite's record."""
    from hcli.lib.ida.plugin.install import get_installed_plugin_records

    for record in get_installed_plugin_records():
        if not record.metadata.plugin.components:
            continue

        try:
            tree = walk_component_tree_from_directory(record.path)
        except ValueError:
            continue

        for _, comp_meta in tree:
            if comp_meta.plugin.name == name:
                return record

    return None


def check_component_name_collisions(
    component_names: set[str],
    *,
    exclude_suite: str | None = None,
) -> list[str]:
    """Check component names against all installed plugins and their components.

    Returns a list of human-readable collision descriptions.
    """
    from hcli.lib.ida.plugin.install import get_installed_plugin_records

    collisions: list[str] = []
    records = get_installed_plugin_records()

    for name in sorted(component_names):
        for record in records:
            if exclude_suite and record.name == exclude_suite:
                continue

            if record.name == name:
                collisions.append(f"'{name}' collides with installed top-level plugin '{record.name}'")
                continue

            if not record.metadata.plugin.components:
                continue

            try:
                tree = walk_component_tree_from_directory(record.path)
            except ValueError:
                continue

            for _, comp_meta in tree:
                if comp_meta.plugin.name == name:
                    collisions.append(f"'{name}' collides with a component of suite '{record.name}'")

    return collisions


def _read_metadata_from_directory(plugin_dir: Path) -> IDAMetadataDescriptor:
    metadata_file = plugin_dir / "ida-plugin.json"
    if not metadata_file.exists():
        raise ValueError(f"ida-plugin.json not found in {plugin_dir}")
    return IDAMetadataDescriptor.model_validate_json(metadata_file.read_text(encoding="utf-8"))

"""Plugin configuration management commands."""

from __future__ import annotations

import json
import logging
import sys

import rich.table
import rich_click as click

from hcli.lib.console import console
from hcli.lib.ida import get_ida_config
from hcli.lib.ida.plugin.install import (
    find_installed_plugin,
    get_metadata_from_plugin_directory,
    resolve_installed_plugin_directory,
)
from hcli.lib.ida.plugin.settings import del_plugin_setting, get_plugin_setting, parse_setting_value, set_plugin_setting

from ._prompt import prompt_plugin_settings

logger = logging.getLogger(__name__)


def resolve_config_plugin_name(plugin_name: str) -> str:
    return find_installed_plugin(plugin_name).name


@click.group()
@click.argument("plugin_name")
@click.pass_context
def config(ctx, plugin_name: str) -> None:
    """Manage plugin configuration settings."""
    ctx.ensure_object(dict)
    ctx.obj["config_plugin_name"] = plugin_name


@config.command()
@click.argument("key")
@click.pass_context
def get(ctx, key: str) -> None:
    """Get a plugin configuration setting."""
    plugin_name = ctx.obj["config_plugin_name"]
    try:
        value = get_plugin_setting(plugin_name, key)
        if isinstance(value, bool):
            console.print("true" if value else "false")
        else:
            console.print(value)
    except KeyError as e:
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()
    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()


@config.command()
@click.argument("key")
@click.argument("value")
@click.pass_context
def set(ctx, key: str, value: str) -> None:
    """Set a plugin configuration setting."""
    plugin_name = ctx.obj["config_plugin_name"]
    try:
        plugin_path = resolve_installed_plugin_directory(plugin_name)
        metadata = get_metadata_from_plugin_directory(plugin_path)
        descr = metadata.plugin.get_setting(key)
        parsed_value = parse_setting_value(descr, value)
        set_plugin_setting(plugin_name, key, parsed_value)
        console.print(f"[green]Set[/green] {plugin_name}.{key}")
    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()


@config.command(name="del")
@click.argument("key")
@click.pass_context
def del_(ctx, key: str) -> None:
    """Delete a plugin configuration setting."""
    plugin_name = ctx.obj["config_plugin_name"]
    try:
        del_plugin_setting(plugin_name, key)
        console.print(f"[green]Deleted[/green] {plugin_name}.{key}")
    except KeyError as e:
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()
    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()


@config.command()
@click.pass_context
def list(ctx) -> None:
    """List all configuration settings for a plugin."""
    plugin_name = ctx.obj["config_plugin_name"]
    try:
        plugin_path = resolve_installed_plugin_directory(plugin_name)
        metadata = get_metadata_from_plugin_directory(plugin_path)

        if not metadata.plugin.settings:
            console.print(f"[grey69]No settings defined for {plugin_name}[/grey69]")
            return

        table = rich.table.Table(show_header=True, box=None)
        table.add_column("Key", style="blue")
        table.add_column("Value", style="default")
        table.add_column("Description", style="grey69")

        for setting in metadata.plugin.settings:
            try:
                value = get_plugin_setting(plugin_name, setting.key)
                if setting.secret:
                    value_str = "********"
                else:
                    value_str = "true" if value is True else ("false" if value is False else str(value))
                if not setting.secret and setting.default is not None and value == setting.default:
                    value_str = f"{value_str} [grey69](default)[/grey69]"
            except KeyError:
                value_str = "[grey69]<not set>[/grey69]"

            description = setting.documentation or ""
            if setting.choices:
                choices_str = ", ".join(setting.choices)
                description = (
                    f"{description}\n[grey69]Choices: {choices_str}[/grey69]"
                    if description
                    else f"[grey69]Choices: {choices_str}[/grey69]"
                )

            table.add_row(setting.key, value_str, description)

        console.print(table)

    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()


@config.command()
@click.pass_context
def setup(ctx) -> None:
    """Interactively re-configure all plugin settings."""
    plugin_name = ctx.obj["config_plugin_name"]
    try:
        plugin_name = resolve_config_plugin_name(plugin_name)
        plugin_path = resolve_installed_plugin_directory(plugin_name)
        metadata = get_metadata_from_plugin_directory(plugin_path)

        if not metadata.plugin.settings:
            console.print(f"[grey69]No settings defined for {plugin_name}[/grey69]")
            return

        promptable = [s for s in metadata.plugin.settings if s.prompt]
        if not promptable:
            console.print(f"[grey69]No interactive settings for {plugin_name}[/grey69]")
            return

        if not console.is_interactive:
            console.print("[red]Error[/red]: setup requires an interactive terminal")
            raise click.Abort()

        existing_config = get_ida_config()
        existing_values: dict[str, str | bool] = {}
        if plugin_name in existing_config.plugins:
            existing_values = dict(existing_config.plugins[plugin_name].settings)

        answers = prompt_plugin_settings(metadata.plugin.settings, existing_values)
        if answers is None:
            raise click.Abort()

        for key, answer in answers.items():
            descr = metadata.plugin.get_setting(key)
            if descr.default == answer:
                continue
            set_plugin_setting(plugin_name, key, answer)

        console.print(f"[green]Configured[/green] {plugin_name}")

    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()


@config.command()
@click.pass_context
def export(ctx) -> None:
    """Export plugin configuration settings as JSON."""
    plugin_name = ctx.obj["config_plugin_name"]
    try:
        plugin_name = resolve_config_plugin_name(plugin_name)
        config = get_ida_config()
        if plugin_name not in config.plugins:
            console.print("{}")
            return

        plugin_config = config.plugins[plugin_name]
        console.print(json.dumps(plugin_config.settings, indent=2))

    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()


@config.command(name="import")
@click.argument("json_input", required=False)
@click.pass_context
def import_(ctx, json_input: str | None) -> None:
    """Import plugin configuration settings from JSON."""
    plugin_name = ctx.obj["config_plugin_name"]
    try:
        plugin_name = resolve_config_plugin_name(plugin_name)
        if json_input:
            data = json.loads(json_input)
        else:
            data = json.load(sys.stdin)

        if not isinstance(data, dict):
            raise ValueError("JSON input must be an object/dict")  # noqa: TRY004

        for key, value in data.items():
            set_plugin_setting(plugin_name, key, value)

        console.print(f"[green]Imported {len(data)} settings for {plugin_name}[/green]")

    except json.JSONDecodeError as e:
        console.print(f"[red]Error[/red]: Invalid JSON: {e}")
        raise click.Abort()
    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()

"""Shared interactive settings prompting for plugin install and config."""

from __future__ import annotations

import questionary

from hcli.lib.console import console
from hcli.lib.ida.plugin import PluginSettingDescriptor
from hcli.lib.ida.plugin.settings import parse_setting_value


def prompt_plugin_settings(
    settings: list[PluginSettingDescriptor],
    existing_values: dict[str, str | bool] | None = None,
) -> dict[str, str | bool] | None:
    """Prompt the user for plugin settings interactively.

    Uses *existing_values* as defaults when available, falling back to
    descriptor defaults.  Empty-string answers for secret settings with
    existing values are omitted (meaning "keep the current value").

    Returns ``None`` if the user cancels the prompt (Ctrl-C).
    """
    if existing_values is None:
        existing_values = {}

    promptable = [s for s in settings if s.prompt]
    if not promptable:
        return {}

    plural = "s" if len(promptable) != 1 else ""
    console.print(f"configure {len(promptable)} setting{plural}:")

    questions: dict[str, questionary.Question] = {}
    secret_with_existing: set[str] = set()

    for setting in promptable:
        existing = existing_values.get(setting.key)

        if setting.type == "boolean":
            if isinstance(existing, bool):
                default_bool = existing
            elif isinstance(setting.default, bool):
                default_bool = setting.default
            else:
                default_bool = False
            questions[setting.key] = questionary.confirm(
                message=setting.name,
                default=default_bool,
            )

        elif setting.choices:
            if existing is not None:
                default_str = str(existing)
            elif setting.default is not None:
                default_str = str(setting.default)
            else:
                default_str = setting.choices[0]
            questions[setting.key] = questionary.select(
                message=setting.name,
                choices=setting.choices,
                default=default_str,
            )

        else:
            allow_empty_for_secret = existing is not None and setting.secret

            def make_validator(s, _allow_empty=allow_empty_for_secret):
                def validate_func(value: str):
                    if _allow_empty and not value:
                        return True
                    if not s.required and not value:
                        return True
                    if s.required and not value:
                        return "This field is required"
                    try:
                        parsed = parse_setting_value(s, value)
                        s.validate_value(parsed)
                        return True
                    except ValueError as e:
                        return str(e)

                return validate_func

            if setting.secret:
                message = setting.name
                if existing is not None:
                    message = f"{setting.name} (leave blank to keep current)"
                    secret_with_existing.add(setting.key)
                questions[setting.key] = questionary.password(
                    message=message,
                    validate=make_validator(setting),
                )
            else:
                if existing is not None:
                    default_str = str(existing)
                elif setting.default is not None:
                    default_str = str(setting.default)
                else:
                    default_str = ""
                questions[setting.key] = questionary.text(
                    message=setting.name,
                    default=default_str,
                    validate=make_validator(setting),
                )

    answers = questionary.form(**questions).ask()
    if answers is None:
        return None

    for key in list(answers.keys()):
        if key in secret_with_existing and answers[key] == "":
            del answers[key]

    return answers

