"""Plugin lint command."""

from __future__ import annotations

import io
import logging
import zipfile
from pathlib import Path

import httpx
import rich_click as click
from pydantic import ValidationError

from hcli.lib.console import console
from hcli.lib.ida.plugin import (
    IDAMetadataDescriptor,
    parse_plugin_version,
    validate_metadata_in_plugin_archive,
)
from hcli.lib.ida.plugin.install import validate_metadata_in_plugin_directory
from hcli.lib.ida.plugin.repo import fetch_plugin_archive
from hcli.lib.util.logging import m

logger = logging.getLogger(__name__)


def _lint_readme_in_directory(plugin_path: Path, source_name: str) -> int:
    """Check for README.md file in plugin directory.

    returns: number of recommendations made
    """
    found_files = []
    has_exact_match = False
    recommendation_count = 0

    for item in plugin_path.iterdir():
        if item.is_file() and item.name == "README.md":
            has_exact_match = True
            break
        if item.is_file() and item.name.lower().startswith("readme"):
            found_files.append(item.name)

    if has_exact_match:
        return 0

    if found_files:
        console.print(
            f"[yellow]Recommendation[/yellow] ({source_name}): rename {found_files[0]} to README.md (exact casing)"
        )
        console.print("  Use 'README.md' with exact casing for consistency and discoverability")
        recommendation_count += 1
    else:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): add a README.md file")
        console.print("  A README helps users understand what your plugin does and how to use it")
        recommendation_count += 1

    return recommendation_count


def _lint_readme_in_archive(zip_data: bytes, metadata_path: Path, source_name: str) -> int:
    """Check for README.md file in plugin archive.

    returns: number of recommendations made
    """
    plugin_dir = metadata_path.parent
    recommendation_count = 0

    with zipfile.ZipFile(io.BytesIO(zip_data), "r") as zip_file:
        namelist = zip_file.namelist()

        found_files = []
        has_exact_match = False

        for file_path in namelist:
            path_obj = Path(file_path)
            if path_obj.parent == plugin_dir:
                if path_obj.name == "README.md":
                    has_exact_match = True
                    break
                if path_obj.name.lower().startswith("readme"):
                    found_files.append(path_obj.name)

        if has_exact_match:
            return 0

        if found_files:
            console.print(
                f"[yellow]Recommendation[/yellow] ({source_name}): rename {found_files[0]} to README.md (exact casing)"
            )
            console.print("  Use 'README.md' with exact casing for consistency and discoverability")
            recommendation_count += 1
        else:
            console.print(f"[yellow]Recommendation[/yellow] ({source_name}): add a README.md file")
            console.print("  A README helps users understand what your plugin does and how to use it")
            recommendation_count += 1

        return recommendation_count


def _check_unexpected_keys(metadata: IDAMetadataDescriptor, source_name: str) -> int:
    """Check for unexpected keys in the plugin metadata.

    returns: number of recommendations made
    """
    recommendation_count = 0

    if hasattr(metadata.plugin, "__pydantic_extra__") and metadata.plugin.__pydantic_extra__:
        extra_keys = sorted(metadata.plugin.__pydantic_extra__.keys())
        for key in extra_keys:
            console.print(f"[yellow]Warning[/yellow] ({source_name}): unexpected key in plugin metadata: '{key}'")
            console.print("  This key is not part of the ida-plugin.json schema and will be ignored")
            recommendation_count += 1

    return recommendation_count


def _lint_metadata(metadata: IDAMetadataDescriptor, source_name: str) -> int:
    """Validate a single plugin metadata and show lint recommendations.

    returns: number of recommendations made
    """
    recommendation_count = 0

    recommendation_count += _check_unexpected_keys(metadata, source_name)

    if not parse_plugin_version(metadata.plugin.version):
        console.print(f"[red]Error[/red] ({source_name}): plugin version should look like 'X.Y.Z'")
        recommendation_count += 1

    if not metadata.plugin.ida_versions:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.idaVersions")
        console.print("  Specify which IDA versions your plugin supports (e.g., ['9.0', '9.1'])")
        recommendation_count += 1

    if not metadata.plugin.description:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.description")
        console.print("  A one-line description improves discoverability in the plugin repository")
        recommendation_count += 1

    if not metadata.plugin.categories:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.categories")
        console.print("  Categories help users find your plugin (e.g., 'malware-analysis', 'decompilation')")
        recommendation_count += 1

    if not metadata.plugin.logo_path:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.logoPath")
        console.print("  A logo image (16:9 aspect ratio) makes your plugin more visually appealing")
        recommendation_count += 1

    if not metadata.plugin.keywords:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.keywords")
        console.print("  Keywords improve search discoverability in the plugin repository")
        recommendation_count += 1

    if not metadata.plugin.license:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.license")
        console.print("  Specify the license (e.g., 'MIT', 'Apache 2.0') to clarify usage rights")
        recommendation_count += 1

    if not metadata.plugin.authors and not metadata.plugin.maintainers:
        console.print(
            f"[red]Error[/red] ({source_name}): ida-plugin.json: provide plugin.authors or plugin.maintainers"
        )
        console.print("  Contact information is required for authors or maintainers")
        recommendation_count += 1
    else:
        # Check if contacts have both name and email for better completeness
        for i, author in enumerate(metadata.plugin.authors):
            if not author.name:
                console.print(
                    f"[yellow]Recommendation[/yellow] ({source_name}): plugin.authors[{i}]: provide an author name"
                )
                recommendation_count += 1
        for i, maintainer in enumerate(metadata.plugin.maintainers):
            if not maintainer.name:
                console.print(
                    f"[yellow]Recommendation[/yellow] ({source_name}): plugin.maintainers[{i}]: provide a maintainer name"
                )
                recommendation_count += 1

    recommendation_count += _check_dependency_specs(metadata, source_name)

    return recommendation_count


def _check_dependency_specs(metadata: IDAMetadataDescriptor, source_name: str) -> int:
    from hcli.lib.ida.plugin.reference import parse_dependency_spec

    recommendation_count = 0
    for i, spec in enumerate(metadata.plugin.dependencies):
        try:
            parse_dependency_spec(spec)
        except ValueError as e:
            console.print(f"[red]Error[/red] ({source_name}): plugin.dependencies[{i}]: invalid spec '{spec}': {e}")
            recommendation_count += 1
    return recommendation_count


def _check_components_in_directory(plugin_path: Path, metadata: IDAMetadataDescriptor, source_name: str) -> int:
    from hcli.lib.ida.plugin.components import (
        find_undeclared_plugins_in_directory,
        walk_component_tree_from_directory,
    )

    recommendation_count = 0

    undeclared = find_undeclared_plugins_in_directory(plugin_path)
    for ud_path, ud_meta in undeclared:
        console.print(
            f"[yellow]Warning[/yellow] ({source_name}): "
            f"subdirectory '{ud_path.name}' contains ida-plugin.json "
            f"(plugin '{ud_meta.plugin.name}') but is not declared as a component"
        )
        recommendation_count += 1

    if not metadata.plugin.components:
        return recommendation_count

    try:
        tree = walk_component_tree_from_directory(plugin_path)
    except ValueError as e:
        console.print(f"[red]Error[/red] ({source_name}): component validation failed: {e}")
        return recommendation_count + 1

    seen_names: set[str] = {metadata.plugin.name}
    for _, comp_meta in tree:
        comp_source = f"{source_name}:{comp_meta.plugin.name}"
        if comp_meta.plugin.name in seen_names:
            console.print(f"[red]Error[/red] ({comp_source}): duplicate component name '{comp_meta.plugin.name}'")
            recommendation_count += 1
        seen_names.add(comp_meta.plugin.name)
        recommendation_count += _lint_metadata(comp_meta, comp_source)

    return recommendation_count


def _check_components_in_archive(
    zip_data: bytes, metadata_path: Path, metadata: IDAMetadataDescriptor, source_name: str
) -> int:
    from hcli.lib.ida.plugin.components import (
        find_undeclared_plugins_in_archive,
        walk_component_tree_from_archive,
    )

    recommendation_count = 0

    undeclared = find_undeclared_plugins_in_archive(zip_data, metadata_path, metadata)
    for ud_path, ud_meta in undeclared:
        console.print(
            f"[yellow]Warning[/yellow] ({source_name}): "
            f"archive contains plugin '{ud_meta.plugin.name}' "
            f"that is not declared as a component"
        )
        recommendation_count += 1

    if not metadata.plugin.components:
        return recommendation_count

    try:
        tree = walk_component_tree_from_archive(zip_data, metadata_path, metadata)
    except ValueError as e:
        console.print(f"[red]Error[/red] ({source_name}): component validation failed: {e}")
        return recommendation_count + 1

    seen_names: set[str] = {metadata.plugin.name}
    for _, comp_meta in tree:
        comp_source = f"{source_name}:{comp_meta.plugin.name}"
        if comp_meta.plugin.name in seen_names:
            console.print(f"[red]Error[/red] ({comp_source}): duplicate component name '{comp_meta.plugin.name}'")
            recommendation_count += 1
        seen_names.add(comp_meta.plugin.name)
        recommendation_count += _lint_metadata(comp_meta, comp_source)

    return recommendation_count


def _lint_plugin_directory(plugin_path: Path) -> int:
    """Lint a plugin in a directory.

    returns: number of recommendations made
    """
    recommendation_count = 0

    metadata_file = plugin_path / "ida-plugin.json"
    if not metadata_file.exists():
        console.print(f"[red]Error[/red]: ida-plugin.json not found in {plugin_path}")
        return 1

    content = metadata_file.read_text(encoding="utf-8")
    try:
        metadata = IDAMetadataDescriptor.model_validate_json(content)
    except ValidationError as e:
        console.print("[red]Error[/red]: ida-plugin.json validation failed")
        for error in e.errors():
            field_path = ".".join(str(loc) for loc in error["loc"])
            error_msg = error["msg"]
            error_type = error["type"]

            if error_type == "missing":
                console.print(f"  [red]Missing required field[/red]: {field_path}")
            else:
                console.print(f"  [red]Invalid value[/red] for {field_path}: {error_msg}")

            recommendation_count += 1

        return recommendation_count

    try:
        validate_metadata_in_plugin_directory(plugin_path)
    except Exception as e:
        console.print(f"[red]Error[/red]: ida-plugin.json validation failed: {e}")
        recommendation_count += 1
        return recommendation_count

    recommendation_count += _lint_metadata(metadata, str(plugin_path))
    recommendation_count += _lint_readme_in_directory(plugin_path, str(plugin_path))
    recommendation_count += _check_components_in_directory(plugin_path, metadata, str(plugin_path))

    return recommendation_count


def _lint_plugin_archive(zip_data: bytes, source_name: str) -> int:
    """Lint plugins in a .zip archive from bytes.

    returns: number of recommendations made
    """
    recommendation_count = 0

    plugins_found = []
    with zipfile.ZipFile(io.BytesIO(zip_data), "r") as zip_file:
        for file_path in zip_file.namelist():
            if not file_path.endswith("ida-plugin.json"):
                continue

            logger.debug(m("found metadata path: %s", file_path))
            with zip_file.open(file_path) as f:
                try:
                    metadata = IDAMetadataDescriptor.model_validate_json(f.read().decode("utf-8"))
                except ValidationError as e:
                    logger.debug(m("failed to validate metadata: %s", file_path, path=file_path, error=str(e)))
                    console.print(f"[red]Error[/red] ({source_name}): {file_path}: ida-plugin.json validation failed")
                    for error in e.errors():
                        field_path = ".".join(str(loc) for loc in error["loc"])
                        error_msg = error["msg"]
                        error_type = error["type"]

                        if error_type == "missing":
                            console.print(f"  [red]Missing required field[/red]: {field_path}")
                        else:
                            console.print(f"  [red]Invalid value[/red] for {field_path}: {error_msg}")
                        recommendation_count += 1
                    continue
                else:
                    logger.debug(m("found valid metadata: %s", file_path))
                    plugins_found.append((Path(file_path), metadata))

    for path, meta in plugins_found:
        logger.debug("found plugin %s at %s", meta.plugin.name, path)

    if not plugins_found:
        console.print(f"[red]Error[/red]: No valid plugins found in archive {source_name}")
        recommendation_count += 1
        return recommendation_count

    for metadata_path, metadata in plugins_found:
        plugin_source_name = f"{source_name}:{metadata_path}"

        try:
            validate_metadata_in_plugin_archive(zip_data, metadata_path, metadata)
        except ValidationError as e:
            console.print(
                f"[red]Error[/red] ({plugin_source_name}): {metadata_path}: ida-plugin.json validation failed"
            )
            for error in e.errors():
                field_path = ".".join(str(loc) for loc in error["loc"])
                error_msg = error["msg"]
                error_type = error["type"]

                if error_type == "missing":
                    console.print(f"  [red]Missing required field[/red]: {field_path}")
                else:
                    console.print(f"  [red]Invalid value[/red] for {field_path}: {error_msg}")
                recommendation_count += 1

            continue

        except Exception as e:
            console.print(f"[red]Error[/red]: {metadata_path}: ida-plugin.json validation failed: {e}")
            recommendation_count += 1
            continue

        recommendation_count += _lint_metadata(metadata, plugin_source_name)
        recommendation_count += _lint_readme_in_archive(zip_data, metadata_path, plugin_source_name)
        recommendation_count += _check_components_in_archive(zip_data, metadata_path, metadata, plugin_source_name)

    return recommendation_count


@click.command()
@click.argument(
    "path",
    metavar="PATH|URL",
)
def lint_plugin_directory(path: str) -> None:
    """Lint an IDA plugin directory, archive (.zip file), or HTTPS URL."""
    recommendation_count = 0
    if path.startswith("https://"):
        logger.info("linting from HTTP URL")
        try:
            buf = fetch_plugin_archive(path)
        except (httpx.ConnectError, httpx.TimeoutException):
            console.print(f"[red]Cannot connect to {path} - network unavailable.[/red]")
            console.print("Please check your internet connection.")
            raise click.Abort()
        except Exception as e:
            console.print(f"[red]Error[/red]: Failed to fetch archive from {path}: {e}")
            raise click.Abort()

        recommendation_count = _lint_plugin_archive(buf, path)

    else:
        plugin_path = Path(path).expanduser().resolve()
        if not plugin_path.exists():
            console.print(f"[red]Error[/red]: Path does not exist: {plugin_path}")
            raise click.Abort()

        if plugin_path.is_file():
            if plugin_path.suffix.lower() != ".zip":
                console.print(f"[red]Error[/red]: File must be a .zip archive: {plugin_path}")
                raise click.Abort()

            zip_data = plugin_path.read_bytes()
            recommendation_count = _lint_plugin_archive(zip_data, str(plugin_path))
        elif plugin_path.is_dir():
            recommendation_count = _lint_plugin_directory(plugin_path)
        else:
            console.print(f"[red]Error[/red]: Path must be a directory or .zip file: {plugin_path}")
            raise click.Abort()

    if not recommendation_count:
        console.print("[green]no recommendations[/green]")

"""Component tree walking and validation for tightly-coupled plugin suites."""

from __future__ import annotations

import logging
from pathlib import Path
from typing import TYPE_CHECKING

from hcli.lib.ida.plugin import (
    IDAMetadataDescriptor,
    get_metadatas_with_paths_from_plugin_archive,
    get_python_dependencies_from_plugin_archive,
    get_python_dependencies_from_plugin_directory,
)

if TYPE_CHECKING:
    from hcli.lib.ida.plugin.install import InstalledPluginRecord

logger = logging.getLogger(__name__)

MAX_COMPONENT_DEPTH = 10


def walk_component_tree_from_directory(
    plugin_dir: Path,
    *,
    _depth: int = 0,
) -> list[tuple[Path, IDAMetadataDescriptor]]:
    """Walk a suite's component tree on disk, validating as we go.

    Returns a flat list of (path, descriptor) for every component found
    at any nesting depth. The suite itself is NOT included.

    Raises:
        ValueError: on missing subdirectory, name mismatch, or depth exceeded.
    """
    if _depth >= MAX_COMPONENT_DEPTH:
        raise ValueError(f"component nesting exceeds maximum depth ({MAX_COMPONENT_DEPTH})")

    metadata = _read_metadata_from_directory(plugin_dir)
    result: list[tuple[Path, IDAMetadataDescriptor]] = []

    for component_name in metadata.plugin.components:
        component_dir = plugin_dir / component_name
        if not component_dir.is_dir():
            raise ValueError(
                f"component '{component_name}' declared by '{metadata.plugin.name}' "
                f"but subdirectory not found: {component_dir}"
            )

        component_metadata = _read_metadata_from_directory(component_dir)
        if component_metadata.plugin.name != component_name:
            raise ValueError(
                f"component directory '{component_name}' contains plugin "
                f"'{component_metadata.plugin.name}' (name mismatch)"
            )

        result.append((component_dir, component_metadata))
        result.extend(walk_component_tree_from_directory(component_dir, _depth=_depth + 1))

    return result


def walk_component_tree_from_archive(
    zip_data: bytes,
    root_path: Path,
    root_metadata: IDAMetadataDescriptor,
    *,
    _depth: int = 0,
    _all_metadatas: dict[str, tuple[Path, IDAMetadataDescriptor]] | None = None,
) -> list[tuple[Path, IDAMetadataDescriptor]]:
    """Walk a suite's component tree inside a zip archive, validating as we go.

    Returns a flat list of (archive_path, descriptor) for every component
    found at any nesting depth. The root manifest is NOT included.

    Raises:
        ValueError: on missing component, name mismatch, or depth exceeded.
    """
    if _depth >= MAX_COMPONENT_DEPTH:
        raise ValueError(f"component nesting exceeds maximum depth ({MAX_COMPONENT_DEPTH})")

    if _all_metadatas is None:
        _all_metadatas = {}
        for path, meta in get_metadatas_with_paths_from_plugin_archive(zip_data):
            _all_metadatas[meta.plugin.name] = (path, meta)

    root_dir = root_path.parent
    result: list[tuple[Path, IDAMetadataDescriptor]] = []

    for component_name in root_metadata.plugin.components:
        if component_name not in _all_metadatas:
            expected_dir = root_dir / component_name
            raise ValueError(
                f"component '{component_name}' declared by '{root_metadata.plugin.name}' "
                f"but no ida-plugin.json found under {expected_dir}"
            )

        comp_path, comp_meta = _all_metadatas[component_name]
        if comp_meta.plugin.name != component_name:
            raise ValueError(
                f"component '{component_name}' manifest has plugin.name '{comp_meta.plugin.name}' (name mismatch)"
            )

        result.append((comp_path, comp_meta))
        result.extend(
            walk_component_tree_from_archive(
                zip_data,
                comp_path,
                comp_meta,
                _depth=_depth + 1,
                _all_metadatas=_all_metadatas,
            )
        )

    return result


def collect_python_dependencies_from_archive(
    zip_data: bytes,
    root_path: Path,
    root_metadata: IDAMetadataDescriptor,
) -> list[str]:
    """Collect pythonDependencies from the root and every component in a suite archive."""
    deps = list(get_python_dependencies_from_plugin_archive(zip_data, root_metadata))
    for _comp_path, comp_meta in walk_component_tree_from_archive(zip_data, root_path, root_metadata):
        deps.extend(get_python_dependencies_from_plugin_archive(zip_data, comp_meta))
    return deps


def collect_python_dependencies_from_directory(
    plugin_dir: Path,
    metadata: IDAMetadataDescriptor,
) -> list[str]:
    """Collect pythonDependencies from the root and every component on disk."""
    deps = list(get_python_dependencies_from_plugin_directory(plugin_dir, metadata))
    if metadata.plugin.components:
        for comp_dir, comp_meta in walk_component_tree_from_directory(plugin_dir):
            deps.extend(get_python_dependencies_from_plugin_directory(comp_dir, comp_meta))
    return deps


def collect_all_component_names_from_archive(
    zip_data: bytes,
    root_path: Path,
    root_metadata: IDAMetadataDescriptor,
) -> set[str]:
    """Collect all component names in a suite archive (at any depth)."""
    tree = walk_component_tree_from_archive(zip_data, root_path, root_metadata)
    return {meta.plugin.name for _, meta in tree}


def find_root_manifest_in_archive(
    zip_data: bytes,
) -> tuple[Path, IDAMetadataDescriptor]:
    """Identify the root manifest in a multi-manifest archive.

    The root is the manifest whose plugin.name is not listed as a component
    by any other manifest in the archive.

    Raises:
        ValueError: if zero or multiple root candidates exist.
    """
    all_items = list(get_metadatas_with_paths_from_plugin_archive(zip_data))
    if not all_items:
        raise ValueError("no valid ida-plugin.json found in archive")

    if len(all_items) == 1:
        return all_items[0]

    referenced_as_component: set[str] = set()
    for _, meta in all_items:
        referenced_as_component.update(meta.plugin.components)

    roots = [(path, meta) for path, meta in all_items if meta.plugin.name not in referenced_as_component]

    if len(roots) == 0:
        raise ValueError("circular component references: every manifest is referenced as a component")
    if len(roots) > 1:
        names = ", ".join(meta.plugin.name for _, meta in roots)
        raise ValueError(f"archive contains multiple unrelated plugins ({names}); specify which one to install")

    return roots[0]


def find_suite_for_component(name: str) -> InstalledPluginRecord | None:
    """If *name* is a component of an installed suite, return that suite's record."""
    from hcli.lib.ida.plugin.install import get_installed_plugin_records

    for record in get_installed_plugin_records():
        if not record.metadata.plugin.components:
            continue

        try:
            tree = walk_component_tree_from_directory(record.path)
        except ValueError:
            continue

        for _, comp_meta in tree:
            if comp_meta.plugin.name == name:
                return record

    return None


def check_component_name_collisions(
    component_names: set[str],
    *,
    exclude_suite: str | None = None,
) -> list[str]:
    """Check component names against all installed plugins and their components.

    Returns a list of human-readable collision descriptions.
    """
    from hcli.lib.ida.plugin.install import get_installed_plugin_records

    collisions: list[str] = []
    records = get_installed_plugin_records()

    for name in sorted(component_names):
        for record in records:
            if exclude_suite and record.name == exclude_suite:
                continue

            if record.name == name:
                collisions.append(f"'{name}' collides with installed top-level plugin '{record.name}'")
                continue

            if not record.metadata.plugin.components:
                continue

            try:
                tree = walk_component_tree_from_directory(record.path)
            except ValueError:
                continue

            for _, comp_meta in tree:
                if comp_meta.plugin.name == name:
                    collisions.append(f"'{name}' collides with a component of suite '{record.name}'")

    return collisions


def find_undeclared_plugins_in_directory(
    plugin_dir: Path,
) -> list[tuple[Path, IDAMetadataDescriptor]]:
    """Find subdirectories that contain ida-plugin.json but are not declared as components.

    Walks the declared component tree first, then scans every subdirectory for
    manifests that weren't referenced. Returns a flat list of (path, metadata)
    for each undeclared plugin found.
    """
    metadata = _read_metadata_from_directory(plugin_dir)
    declared_names = set(metadata.plugin.components)

    try:
        tree = walk_component_tree_from_directory(plugin_dir)
    except ValueError:
        tree = []
    all_declared_dirs = {path for path, _ in tree}
    all_declared_dirs.add(plugin_dir)

    undeclared: list[tuple[Path, IDAMetadataDescriptor]] = []
    _scan_for_undeclared(plugin_dir, all_declared_dirs, undeclared)
    return undeclared


def _scan_for_undeclared(
    directory: Path,
    declared_dirs: set[Path],
    result: list[tuple[Path, IDAMetadataDescriptor]],
) -> None:
    """Recursively scan for undeclared plugin subdirectories."""
    for child in sorted(directory.iterdir()):
        if not child.is_dir():
            continue
        manifest = child / "ida-plugin.json"
        if not manifest.exists():
            continue
        if child in declared_dirs:
            _scan_for_undeclared(child, declared_dirs, result)
        else:
            try:
                meta = _read_metadata_from_directory(child)
            except ValueError:
                continue
            result.append((child, meta))


def find_undeclared_plugins_in_archive(
    zip_data: bytes,
    root_path: Path,
    root_metadata: IDAMetadataDescriptor,
) -> list[tuple[Path, IDAMetadataDescriptor]]:
    """Find manifests in the archive that are not part of the declared component tree.

    Returns (path, metadata) pairs for each undeclared plugin.
    """
    all_items = list(get_metadatas_with_paths_from_plugin_archive(zip_data))

    try:
        tree = walk_component_tree_from_archive(zip_data, root_path, root_metadata)
    except ValueError:
        tree = []
    declared_names = {root_metadata.plugin.name}
    declared_names.update(meta.plugin.name for _, meta in tree)

    undeclared = []
    for path, meta in all_items:
        if meta.plugin.name not in declared_names:
            undeclared.append((path, meta))
    return undeclared


def _read_metadata_from_directory(plugin_dir: Path) -> IDAMetadataDescriptor:
    metadata_file = plugin_dir / "ida-plugin.json"
    if not metadata_file.exists():
        raise ValueError(f"ida-plugin.json not found in {plugin_dir}")
    return IDAMetadataDescriptor.model_validate_json(metadata_file.read_text(encoding="utf-8"))

